def solution(n, start, groups):
    know = [False] * n
    for p in start:
        know[p] = True
    answer = 0
    while know.count(True) < n:
        nxt = know[:]
        for g in groups:
            found = False
            for p in g:
                if know[p]:
                    found = True
            if found:
                for p in g:
                    nxt[p] = True
        if nxt == know:
            return -1
        know = nxt
        answer += 1
    return answer

