    left = [0] * n
    tried = [False] * n
    for p in starters:
        left[p] = t
        tried[p] = True
    day = 0
    while max(left) > 0:
        day += 1
        new = []
        for c in crews:
            active = False
            for p in c:
                if left[p] > 0:
                    active = True
            if active:
                for p in c:
                    if not tried[p]:
                        tried[p] = True
                        new.append(p)
        for i in range(n):
            if left[i] > 0:
                left[i] -= 1
        for p in new:
            left[p] = t
    answer = [day, tried.count(True)]
    return answer

